            return [
                { key: 'results.leverA', label: 'Access (A)', i18nKey: 'col_lever_a', formatter: (v) => '$' + (v / 1000000).toFixed(2) + 'M' },
                { key: 'results.leverB', label: 'KOL (B)', i18nKey: 'col_lever_b', formatter: (v) => '$' + (v / 1000000).toFixed(2) + 'M' },
